begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('92000000-0000-4000-8000-000000000001','session-end-owner@example.test',now()),
 ('92000000-0000-4000-8000-000000000002','session-end-other@example.test',now());
create temporary table end_state(name text primary key,value jsonb);
grant select,insert,update on end_state to authenticated;
select ok(not has_function_privilege('anon','public.end_training_session(uuid,uuid,integer)','execute'),'guests cannot execute End');
select ok(not has_column_privilege('authenticated','public.training_sessions','ended_at','update'),'learners cannot forge terminal timestamps');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into end_state values('zero',public.start_training_session('92000000-0000-4000-8000-000000000010')->'session');
insert into end_state select 'zero-ended',public.end_training_session((value->>'id')::uuid,'92000000-0000-4000-8000-000000000011',0)->'session' from end_state where name='zero';
select is(value->>'status','ended','zero-answer end is a distinct terminal status') from end_state where name='zero-ended';
select is(value->>'phase','ended','ended phase is persisted') from end_state where name='zero-ended';
select is(value->>'revision','1','zero-answer end increments exactly once') from end_state where name='zero-ended';
select ok(value->'currentIndex'='null'::jsonb and value->'completedAt'='null'::jsonb and value->>'endedAt'=value->>'updatedAt','ended metadata is terminal and not completed') from end_state where name='zero-ended';
select is(value->'items',(select value->'items' from end_state where name='zero'),'ending preserves all pinned items without inventing answers') from end_state where name='zero-ended';
select is(public.get_active_training_session(),null::jsonb,'ended run is not active');
select is(public.end_training_session((value->>'id')::uuid,'92000000-0000-4000-8000-000000000011',0)->>'replayed','true','identical End retry uses receipt before revision check') from end_state where name='zero';
select throws_ok(format('select public.end_training_session(%L,%L,1)',value->>'id','92000000-0000-4000-8000-000000000011'),'P0001','IDEMPOTENCY_CONFLICT','same UUID cannot change expected revision') from end_state where name='zero';
select throws_ok(format('select public.end_training_session(%L,%L,1)',value->>'id','92000000-0000-4000-8000-000000000012'),'P0001','SESSION_CONFLICT','a fresh command cannot end an ended run again') from end_state where name='zero';
select throws_ok(format('select public.submit_session_answer(%L,%L,%L,%L,1)',value->>'id',value->'items'->0->>'id',value->'items'->0->'challenge'->'options'->0->>'id','92000000-0000-4000-8000-000000000013'),'P0001','SESSION_CONFLICT','ended run cannot save an unanswered item') from end_state where name='zero';
insert into end_state values('partial',public.start_training_session('92000000-0000-4000-8000-000000000020')->'session');
select isnt((select value->>'id' from end_state where name='partial'),(select value->>'id' from end_state where name='zero'),'End releases the active slot for a separate new start');
insert into end_state select 'review',public.submit_session_answer((value->>'id')::uuid,(value->'items'->0->>'id')::uuid,value->'items'->0->'challenge'->'options'->0->>'id','92000000-0000-4000-8000-000000000021',0)->'session' from end_state where name='partial';
select throws_ok(format('select public.end_training_session(%L,%L,0)',value->>'id','92000000-0000-4000-8000-000000000022'),'P0001','SESSION_CONFLICT','a saved answer invalidates a stale End confirmation') from end_state where name='review';
insert into end_state select 'review-ended',public.end_training_session((value->>'id')::uuid,'92000000-0000-4000-8000-000000000022',1)->'session' from end_state where name='review';
select is(value->>'revision','2','one-answer review ends at exact revision two') from end_state where name='review-ended';
select is(value->'items',(select value->'items' from end_state where name='review'),'partial end preserves the exact answer and other null answers') from end_state where name='review-ended';
select is(public.submit_session_answer((value->>'id')::uuid,(value->'items'->0->>'id')::uuid,value->'items'->0->'challenge'->'options'->0->>'id','92000000-0000-4000-8000-000000000021',0)->'session'->>'phase','ended','an old answer receipt returns current ended state') from end_state where name='partial';
select throws_ok(format('select public.advance_training_session(%L,%L,%L,2)',value->>'id',value->'items'->0->>'id','92000000-0000-4000-8000-000000000023'),'P0001','SESSION_CONFLICT','ended review cannot advance') from end_state where name='review-ended';
select is((select entry->>'status' from jsonb_array_elements(public.list_training_sessions()->'sessions') entry where entry->>'id'=(select value->>'id' from end_state where name='review-ended')),'ended','history projects the ended status');
select is((select entry->>'answeredCount' from jsonb_array_elements(public.list_training_sessions()->'sessions') entry where entry->>'id'=(select value->>'id' from end_state where name='review-ended')),'1','history retains partial saved count');
insert into end_state values('setup',public.start_training_session('92000000-0000-4000-8000-000000000030')->'session');
select public.submit_session_answer((value->>'id')::uuid,(value->'items'->0->>'id')::uuid,value->'items'->0->'challenge'->'options'->0->>'id','92000000-0000-4000-8000-000000000031',0) from end_state where name='setup';
select public.advance_training_session((value->>'id')::uuid,(value->'items'->0->>'id')::uuid,'92000000-0000-4000-8000-000000000032',1) from end_state where name='setup';
select is(public.end_training_session((value->>'id')::uuid,'92000000-0000-4000-8000-000000000033',2)->'session'->>'revision','3','one-answer next setup ends at exact revision three') from end_state where name='setup';
insert into end_state values('single',public.start_selected_training_session('92000000-0000-4000-8000-000000000040','{"kind":"scenario","scenarioId":"bind-clove-utility-window"}')->'session');
select public.submit_session_answer((value->>'id')::uuid,(value->'items'->0->>'id')::uuid,value->'items'->0->'challenge'->'options'->0->>'id','92000000-0000-4000-8000-000000000041',0) from end_state where name='single';
select throws_ok(format('select public.end_training_session(%L,%L,1)',value->>'id','92000000-0000-4000-8000-000000000042'),'P0001','SESSION_CONFLICT','all answers saved requires normal Finish') from end_state where name='single';
select is(public.advance_training_session((value->>'id')::uuid,(value->'items'->0->>'id')::uuid,'92000000-0000-4000-8000-000000000043',1)->'session'->>'status','completed','normal full completion remains available') from end_state where name='single';
select throws_ok(format('select public.end_training_session(%L,%L,2)',value->>'id','92000000-0000-4000-8000-000000000044'),'P0001','SESSION_CONFLICT','completed history cannot become early-ended') from end_state where name='single';
select set_config('request.jwt.claims','{"sub":"92000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok(format('select public.end_training_session(%L,%L,0)',value->>'id','92000000-0000-4000-8000-000000000050'),'P0001','SESSION_NOT_FOUND','foreign owner cannot end or inspect session') from end_state where name='zero';
select throws_ok($$select public.end_training_session(null,'92000000-0000-4000-8000-000000000051',0)$$,'P0001','INVALID_REQUEST','null End identity is rejected');
reset role;
select throws_ok($$update public.training_sessions set phase='setup',current_index=0,ended_at=null where phase='ended'$$,'P0001','IMMUTABLE_RECORD','even maintenance cannot resurrect ended history in place');
select is((select count(*)::integer from private.session_commands where operation='end'),3,'failed/replayed commands do not add terminal transitions');
select * from finish();
rollback;
